const fs = require("fs");

const TYPESENSE_URL = process.env.TYPESENSE_URL || "http://127.0.0.1:8108";
const API_KEY_FILE = process.env.TYPESENSE_API_KEY_FILE || "/etc/typesense-api-key";
const COLLECTION = "products";

let apiKey = null;
function getApiKey() {
  if (apiKey === null) {
    apiKey = fs.readFileSync(API_KEY_FILE, "utf8").trim();
  }
  return apiKey;
}

async function tsFetch(path, options = {}) {
  const url = `${TYPESENSE_URL}${path}`;
  const res = await fetch(url, {
    ...options,
    headers: {
      "X-TYPESENSE-API-KEY": getApiKey(),
      "Content-Type": "application/json",
      ...(options.headers || {}),
    },
  });
  return res;
}

// Ensure the `products` collection exists with the expected schema.
async function ensureCollection() {
  const res = await tsFetch(`/collections/${COLLECTION}`);
  if (res.status === 200) {
    return;
  }
  if (res.status !== 404) {
    const body = await res.text();
    throw new Error(`Failed to check collection: ${res.status} ${body}`);
  }

  const createRes = await tsFetch("/collections", {
    method: "POST",
    body: JSON.stringify({
      name: COLLECTION,
      fields: [
        { name: "name", type: "string" },
        { name: "category", type: "string", facet: true },
        { name: "price", type: "float" },
      ],
    }),
  });

  if (!createRes.ok) {
    const body = await createRes.text();
    throw new Error(`Failed to create collection: ${createRes.status} ${body}`);
  }
}

// Upsert an array of product documents ({id, name, category, price}).
// Uses Typesense's import endpoint with action=upsert so re-indexing the
// same document id updates it in place instead of creating a duplicate.
async function upsertDocuments(docs) {
  if (!docs || docs.length === 0) return 0;

  const body = docs.map((d) => JSON.stringify(d)).join("\n");
  const res = await tsFetch(
    `/collections/${COLLECTION}/documents/import?action=upsert`,
    {
      method: "POST",
      body,
      headers: { "Content-Type": "text/plain" },
    }
  );

  const text = await res.text();
  if (!res.ok) {
    throw new Error(`Failed to import documents: ${res.status} ${text}`);
  }

  const results = text
    .trim()
    .split("\n")
    .filter(Boolean)
    .map((line) => JSON.parse(line));

  const failures = results.filter((r) => !r.success);
  if (failures.length > 0) {
    throw new Error(`Some documents failed to import: ${JSON.stringify(failures)}`);
  }

  return results.length;
}

function escapeFilterValue(value) {
  // Typesense allows backtick-wrapped filter values, which safely handles
  // values containing spaces, commas, etc. Backticks themselves are not
  // expected in category names for this application.
  return `\`${String(value)}\``;
}

// Runs a saved-search definition against the live Typesense index and
// returns the *complete* set of matching document ids (across all pages).
async function searchAllMatchingIds({ q, category, max_price }) {
  const trimmedQ = (q || "").trim();
  const qParam = trimmedQ === "" ? "*" : trimmedQ;

  const filters = [];
  if (category && String(category).trim() !== "") {
    filters.push(`category:=${escapeFilterValue(category)}`);
  }
  if (max_price !== null && max_price !== undefined && max_price !== "") {
    filters.push(`price:<=${Number(max_price)}`);
  }

  const perPage = 250;
  const ids = new Set();
  let page = 1;
  let found = Infinity;

  while ((page - 1) * perPage < found) {
    const params = new URLSearchParams();
    params.set("q", qParam);
    params.set("query_by", "name");
    if (filters.length > 0) params.set("filter_by", filters.join(" && "));
    params.set("per_page", String(perPage));
    params.set("page", String(page));
    params.set("include_fields", "id");

    const res = await tsFetch(
      `/collections/${COLLECTION}/documents/search?${params.toString()}`
    );
    const data = await res.json();
    if (!res.ok) {
      throw new Error(`Search failed: ${res.status} ${JSON.stringify(data)}`);
    }

    found = data.found;
    for (const hit of data.hits || []) {
      ids.add(hit.document.id);
    }

    if (!data.hits || data.hits.length < perPage) break;
    page++;
  }

  return ids;
}

module.exports = {
  ensureCollection,
  upsertDocuments,
  searchAllMatchingIds,
};

const path = require("path");
const fs = require("fs");
const express = require("express");
const { v4: uuidv4 } = require("uuid");
const ts = require("./typesense");

const PORT = process.env.PORT || 8080;
const DATA_DIR = path.join(__dirname, "data");
const BASELINE_PATH = path.join(DATA_DIR, "baseline.json");
const CATALOG_PATH = path.join(DATA_DIR, "catalog.json");

const app = express();
app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

// In-memory store of saved searches. Keyed by id.
// Each entry: { id, name, q, category, max_price, match_count, new_count,
//               previousIds: Set<string> | undefined }
const savedSearches = new Map();

function sanitize(entry) {
  return {
    id: entry.id,
    name: entry.name,
    q: entry.q,
    category: entry.category,
    max_price: entry.max_price,
    match_count: entry.match_count,
    new_count: entry.new_count,
  };
}

async function checkSavedSearch(entry) {
  const currentIds = await ts.searchAllMatchingIds({
    q: entry.q,
    category: entry.category,
    max_price: entry.max_price,
  });

  let newCount = 0;
  if (entry.previousIds !== undefined) {
    for (const id of currentIds) {
      if (!entry.previousIds.has(id)) newCount++;
    }
  }

  entry.previousIds = currentIds;
  entry.match_count = currentIds.size;
  entry.new_count = newCount;
  return entry;
}

// ---- API routes ----

app.post("/api/saved-searches", async (req, res) => {
  const { name, q, category, max_price } = req.body || {};

  if (typeof name !== "string" || name.trim() === "") {
    return res.status(400).json({ error: "name is required" });
  }

  const entry = {
    id: uuidv4(),
    name,
    q: typeof q === "string" ? q : "",
    category: typeof category === "string" ? category : "",
    max_price:
      max_price === undefined || max_price === null || max_price === ""
        ? null
        : Number(max_price),
    match_count: null,
    new_count: null,
    previousIds: undefined,
  };

  savedSearches.set(entry.id, entry);
  res.status(201).json(sanitize(entry));
});

app.get("/api/saved-searches", (req, res) => {
  res.status(200).json(Array.from(savedSearches.values()).map(sanitize));
});

app.post("/api/saved-searches/:id/check", async (req, res) => {
  const entry = savedSearches.get(req.params.id);
  if (!entry) {
    return res.status(404).json({ error: "saved search not found" });
  }
  try {
    await checkSavedSearch(entry);
    res.status(200).json(sanitize(entry));
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: String(err.message || err) });
  }
});

app.post("/api/check-all", async (req, res) => {
  try {
    const entries = Array.from(savedSearches.values());
    for (const entry of entries) {
      await checkSavedSearch(entry);
    }
    res.status(200).json(entries.map(sanitize));
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: String(err.message || err) });
  }
});

app.post("/api/ingest", async (req, res) => {
  const { documents } = req.body || {};
  if (!Array.isArray(documents)) {
    return res.status(400).json({ error: "documents must be an array" });
  }

  try {
    const normalized = documents.map((d) => ({
      id: String(d.id),
      name: String(d.name),
      category: typeof d.category === "string" ? d.category : "",
      price: Number(d.price),
    }));
    const ingested = await ts.upsertDocuments(normalized);
    res.status(200).json({ ingested });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: String(err.message || err) });
  }
});

// Convenience endpoint (not part of the required contract) so the UI can
// present the ingest catalog documents to choose from.
app.get("/api/catalog", (req, res) => {
  try {
    const catalog = JSON.parse(fs.readFileSync(CATALOG_PATH, "utf8"));
    res.status(200).json(catalog);
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: String(err.message || err) });
  }
});

async function start() {
  await ts.ensureCollection();

  const baseline = JSON.parse(fs.readFileSync(BASELINE_PATH, "utf8"));
  await ts.upsertDocuments(
    baseline.map((d) => ({
      id: String(d.id),
      name: String(d.name),
      category: typeof d.category === "string" ? d.category : "",
      price: Number(d.price),
    }))
  );

  app.listen(PORT, () => {
    console.log(`Saved Search Alerts app listening on port ${PORT}`);
  });
}

start().catch((err) => {
  console.error("Failed to start application:", err);
  process.exit(1);
});

:root {
  --bg: #0f1420;
  --panel: #171e2e;
  --border: #2a3448;
  --text: #e6ebf5;
  --muted: #93a0b8;
  --accent: #4f8cff;
  --new: #ff6b6b;
  --ok: #33c481;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
}

header {
  padding: 20px 32px;
  border-bottom: 1px solid var(--border);
}

header h1 {
  margin: 0;
  font-size: 22px;
}

.subtitle {
  font-weight: 400;
  color: var(--muted);
  font-size: 15px;
  margin-left: 10px;
}

main {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  padding: 24px 32px;
  max-width: 1100px;
  margin: 0 auto;
}

#searches-panel { grid-column: 1 / -1; }
#ingest-panel { grid-column: 1 / -1; }

.panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 18px 20px;
}

.panel h2 {
  margin-top: 0;
  font-size: 17px;
}

.panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

form label {
  display: block;
  margin-bottom: 12px;
  font-size: 13px;
  color: var(--muted);
}

form input {
  display: block;
  width: 100%;
  margin-top: 4px;
  padding: 8px 10px;
  border-radius: 6px;
  border: 1px solid var(--border);
  background: #0f1420;
  color: var(--text);
  font-size: 14px;
}

button {
  background: var(--accent);
  color: white;
  border: none;
  padding: 9px 16px;
  border-radius: 6px;
  cursor: pointer;
  font-size: 14px;
}

button:hover { filter: brightness(1.1); }
button.secondary { background: #2a3448; }

.hint { color: var(--muted); font-size: 13px; }

ul { list-style: none; padding: 0; margin: 0; }

#saved-search-list li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 14px;
  border: 1px solid var(--border);
  border-radius: 8px;
  margin-bottom: 10px;
  background: #121826;
}

.ss-info { display: flex; flex-direction: column; gap: 3px; }
.ss-name { font-weight: 600; }
.ss-meta { color: var(--muted); font-size: 12px; }

.ss-stats { display: flex; align-items: center; gap: 10px; }

.badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 26px;
  padding: 3px 8px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600;
}

.badge.match-count { background: #1d2b45; color: var(--ok); }
.badge.new-count { background: #3a1d24; color: var(--new); }
.badge.new-count.zero { opacity: 0.55; }

#catalog-list li {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 4px;
  border-bottom: 1px solid var(--border);
}

#catalog-list li:last-child { border-bottom: none; }

.catalog-name { font-weight: 500; }
.catalog-meta { color: var(--muted); font-size: 12px; }

#ingest-status { margin-left: 12px; color: var(--muted); font-size: 13px; }

const savedSearchListEl = document.getElementById("saved-search-list");
const catalogListEl = document.getElementById("catalog-list");
const createForm = document.getElementById("create-form");
const checkAllBtn = document.getElementById("check-all-btn");
const ingestBtn = document.getElementById("ingest-selected-btn");
const ingestStatus = document.getElementById("ingest-status");

async function api(path, options) {
  const res = await fetch(path, {
    headers: { "Content-Type": "application/json" },
    ...options,
  });
  if (!res.ok) {
    let body;
    try {
      body = await res.json();
    } catch (e) {
      body = { error: res.statusText };
    }
    throw new Error(body.error || `Request failed: ${res.status}`);
  }
  return res.json();
}

function renderSavedSearches(searches) {
  savedSearchListEl.innerHTML = "";
  if (searches.length === 0) {
    savedSearchListEl.innerHTML =
      '<li class="hint" style="border:none;background:none;">No saved searches yet.</li>';
    return;
  }

  for (const s of searches) {
    const li = document.createElement("li");
    li.dataset.id = s.id;

    const metaParts = [];
    metaParts.push(`q: ${s.q ? s.q : "*"}`);
    metaParts.push(`category: ${s.category ? s.category : "any"}`);
    metaParts.push(`max price: ${s.max_price === null ? "any" : s.max_price}`);

    const matchLabel = s.match_count === null ? "—" : s.match_count;
    const newLabel = s.new_count === null ? "—" : s.new_count;
    const newIsZero = s.new_count === 0 || s.new_count === null;

    li.innerHTML = `
      <div class="ss-info">
        <span class="ss-name">${escapeHtml(s.name)}</span>
        <span class="ss-meta">${escapeHtml(metaParts.join(" · "))}</span>
      </div>
      <div class="ss-stats">
        <span class="badge match-count" title="Current match count">matches: ${matchLabel}</span>
        <span class="badge new-count ${newIsZero ? "zero" : ""}" title="New matches since last check">new: ${newLabel}</span>
        <button class="secondary check-btn" data-id="${s.id}">Check</button>
      </div>
    `;
    savedSearchListEl.appendChild(li);
  }

  savedSearchListEl.querySelectorAll(".check-btn").forEach((btn) => {
    btn.addEventListener("click", async () => {
      btn.disabled = true;
      try {
        await api(`/api/saved-searches/${btn.dataset.id}/check`, { method: "POST" });
        await loadSavedSearches();
      } catch (e) {
        alert(e.message);
      } finally {
        btn.disabled = false;
      }
    });
  });
}

function escapeHtml(str) {
  return String(str).replace(/[&<>"']/g, (c) => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;",
  }[c]));
}

async function loadSavedSearches() {
  const searches = await api("/api/saved-searches");
  renderSavedSearches(searches);
}

async function loadCatalog() {
  const catalog = await api("/api/catalog");
  catalogListEl.innerHTML = "";
  for (const doc of catalog) {
    const li = document.createElement("li");
    li.innerHTML = `
      <input type="checkbox" class="catalog-checkbox" value="${escapeHtml(doc.id)}" />
      <span class="catalog-name">${escapeHtml(doc.name)}</span>
      <span class="catalog-meta">${escapeHtml(doc.category)} · $${doc.price}</span>
    `;
    li.dataset.doc = JSON.stringify(doc);
    catalogListEl.appendChild(li);
  }
}

createForm.addEventListener("submit", async (e) => {
  e.preventDefault();
  const name = document.getElementById("f-name").value.trim();
  const q = document.getElementById("f-q").value;
  const category = document.getElementById("f-category").value.trim();
  const maxPriceRaw = document.getElementById("f-max-price").value;
  const max_price = maxPriceRaw === "" ? null : Number(maxPriceRaw);

  try {
    await api("/api/saved-searches", {
      method: "POST",
      body: JSON.stringify({ name, q, category, max_price }),
    });
    createForm.reset();
    await loadSavedSearches();
  } catch (err) {
    alert(err.message);
  }
});

checkAllBtn.addEventListener("click", async () => {
  checkAllBtn.disabled = true;
  try {
    await api("/api/check-all", { method: "POST" });
    await loadSavedSearches();
  } catch (err) {
    alert(err.message);
  } finally {
    checkAllBtn.disabled = false;
  }
});

ingestBtn.addEventListener("click", async () => {
  const checked = Array.from(
    catalogListEl.querySelectorAll(".catalog-checkbox:checked")
  );
  if (checked.length === 0) {
    ingestStatus.textContent = "Select at least one document.";
    return;
  }

  const documents = checked.map((cb) => JSON.parse(cb.closest("li").dataset.doc));

  ingestBtn.disabled = true;
  ingestStatus.textContent = "Ingesting…";
  try {
    const result = await api("/api/ingest", {
      method: "POST",
      body: JSON.stringify({ documents }),
    });
    ingestStatus.textContent = `Ingested ${result.ingested} document(s).`;
    checked.forEach((cb) => (cb.checked = false));
  } catch (err) {
    ingestStatus.textContent = err.message;
  } finally {
    ingestBtn.disabled = false;
  }
});

loadSavedSearches().catch((err) => console.error(err));
loadCatalog().catch((err) => console.error(err));

